  const { fps } = useVideoConfig();

  const props = item.props || {};
  const quoteText = props.quoteText;
  const fontFamily = props.fontFamily;
  const cardColor = props.cardColor;
  const cardOpacity = typeof props.cardOpacity === 'number' ? props.cardOpacity : 0.88;
  const textColor = props.textColor;
  const cardBorderRadius = props.cardBorderRadius;
  const wordDelay = props.wordDelay;
  const slideInDuration = props.slideInDuration;
  const fontSize = props.fontSize;

