                fill={textColor}
              />
            </svg>
          </div>
          <div style={{ fontFamily, color: textColor, fontSize, lineHeight: 1.25, fontWeight: 'bold', letterSpacing: '-0.02em', marginTop: 10 }}>
            {words.map((word, i) => {
